import { Suspense } from "react";
import EmployeeRecord from "@/components/employee-record";
import LoadingEmployee from "../loading";

type EditEmployeePageProps = {
  params: Promise<{ id: string }>;
};

export default function EditEmployeePage({ params }: EditEmployeePageProps) {
  return (
    <Suspense fallback={<LoadingEmployee />}>
      <EditEmployeeContent params={params} />
    </Suspense>
  );
}

async function EditEmployeeContent({ params }: EditEmployeePageProps) {
  const { id } = await params;
  return <EmployeeRecord key={id} id={id} edit />;
}
